async function enqueue(type, payload) {
  const jobId = await ids.next();
  await queue.push({ jobId, type, payload, attempts: 0 });
  return jobId;   // caller can poll status by jobId if it needs to
}

// NAIVE: works until a crash lands between these two lines
async function workerNaive() {
  const job = await queue.pop();
  await process(job);       // <-- crash here, then queue redelivers
  await queue.ack(job);
}

async function process(job) {
  const done = await db.processed.exists(job.jobId);
  if (done) return;                       // already handled, redelivery is a no-op

  await runHandler(job.type, job.payload);
  await db.processed.insertIfAbsent(job.jobId);  // atomic with completion
}

async function pop() {
  // atomically: fetch oldest visible job, hide it for VISIBILITY_SECONDS
  return queue.reserve({ visibilityTimeout: 30 });
}

// if processing legitimately takes longer, worker extends it explicitly:
async function extend(job) {
  await queue.changeVisibility(job, 30);
}

async function onFailure(job, err) {
  job.attempts += 1;
  if (job.attempts >= 5) return deadLetter.push({ job, err: err.message });

  const delay = 2 ** job.attempts * 1000;
  return queue.push({ ...job, availableAt: Date.now() + delay });
}

// Global order:      not guaranteed once you have > 1 worker
// Per-key order:      guaranteed if partitioned by that key

function partitionFor(job) {
  return hash(job.payload.userId) % NUM_PARTITIONS;
}
